!function(i){function e(e){for(var t,n,s=e[0],o=e[1],u=e[2],c=0,g=[];c<s.length;c++)n=s[c],Object.prototype.hasOwnProperty.call(a,n)&&a[n]&&g.push(a[n][0]),a[n]=0;for(t in o)Object.prototype.hasOwnProperty.call(o,t)&&(i[t]=o[t]);for(m&&m(e);g.length;)g.shift()();return p.push.apply(p,u||[]),r()}function r(){for(var i,e=0;e<p.length;e++){for(var r,n=p[e],s=!0,o=1;o<n.length;o++)r=n[o],0!==a[r]&&(s=!1);s&&(p.splice(e--,1),i=t(t.s=n[0]))}return i}function t(e){if(n[e])return n[e].exports;var r=n[e]={i:e,l:!1,exports:{}};return i[e].call(r.exports,r,r.exports,t),r.l=!0,r.exports}var n={},a={17:0},p=[];t.m=i,t.c=n,t.d=function(i,e,r){t.o(i,e)||Object.defineProperty(i,e,{enumerable:!0,get:r})},t.r=function(i){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(i,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(i,"__esModule",{value:!0})},t.t=function(i,e){if(1&e&&(i=t(i)),8&e)return i;if(4&e&&"object"==typeof i&&i&&i.__esModule)return i;var r=Object.create(null);if(t.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:i}),2&e&&"string"!=typeof i)for(var n in i)t.d(r,n,function(e){return i[e]}.bind(null,n));return r},t.n=function(i){var e=i&&i.__esModule?function(){return i.default}:function(){return i};return t.d(e,"a",e),e},t.o=function(i,e){return Object.prototype.hasOwnProperty.call(i,e)},t.p="";var s=window.webpackJsonp=window.webpackJsonp||[],o=s.push.bind(s);s.push=e,s=s.slice();for(var u=0;u<s.length;u++)e(s[u]);var m=o;p.push([89,0]),r()}({89:function(i,e,r){"use strict";r.r(e);var t=r(0);Object(t.a)("us","army",r(90),r(1))},90:function(i){i.exports=JSON.parse('{"category":[{"name":"美国","link":"us_shortcut"},{"name":"陆战武器","link":"us_army"},{"name":"轻武器","link":"us_army#us_army_iw"}],"model":"M1918“勃朗宁”自动步枪","description":"<h6>综述：</h6><p>1918年，美国著名枪械师约翰·摩西·勃朗宁研制了一种全自动步枪，即M1918“勃朗宁”自动步枪（简称“BAR”）。该枪二战期间改型为M1918A2，继续被美军使用。</p><p>二战中，M1918“勃朗宁”自动步枪主要装备美国海军陆战队，也有一些装备了美国和盟国的陆军部队，通常一个步兵班会配备2～3支。为了减少后座力，M1918A2配有两脚支架，阵地战时，可类似轻机枪般地进行连射。但在太平洋战场上，美国海军陆战队士兵为了对付丛林中的日军伏击，通常都会弃用两脚架而直接端在手中，在队伍的一前一后戒备，作为战斗班组行进时反伏击的压制火力使用。该枪坚固耐用，有很强的杀伤威力，特别适合在丛林作战，因此受到了美国海军陆战队的广泛好评。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/us/army/us_army_iwM1918Rifle_10.jpg","description":"<h6>M1918A2“勃朗宁”自动步枪</h6><p></p><p>基本技术数据：</p><p>口径：7.62毫米；</p><p>枪全长：1214毫米，其中枪管长：610毫米；</p><p>枪全重：7.5公斤；</p><p>枪口初速：805米/秒；</p><p>自动射速：（慢速）300-450发/分钟，（快速）500-550发/分钟；</p><p>子弹容量：20发。</p>","caption":""}],"part2title":"战场上的M1918“勃朗宁”自动步枪","part2description":"","part2content":[{"image":"imgs/us/army/us_army_iwM1918Rifle_20.jpg","description":"（图左）1942年，美军第9步兵师一名手持M1918A2“勃朗宁”自动步枪的士兵。（图中）1944-1945年间，太平洋战场上一名手持M1918A2“勃朗宁”自动步枪作战斗状的美国海军陆战队士兵。（图右）1945年，美军第77步兵师一名手持M1918A2“勃朗宁”自动步枪的士兵。","caption":""},{"image":"imgs/us/army/us_army_iwM1918Rifle_21.jpg","description":"绘画：1945年，太平洋战场的硫磺岛战役中，刚登陆上岸的美国海军陆战队士兵埋伏在沙丘上准备向日军进攻，前方一名士兵拿的是一支M1918A2“勃朗宁”自动步枪。","caption":""},{"image":"imgs/us/army/us_army_iwM1918Rifle_22.jpg","description":"1945年，太平洋战场关岛战役，一名美国海军陆战队士兵正在检查手中的M1918A2“勃朗宁”自动步枪。","caption":""},{"image":"imgs/us/army/us_army_iwM1918Rifle_23.jpg","description":"1945年，太平洋战场，一支美国海军陆战队的战斗小队正在棕榈树种植园里搜索日军，左前方一名士兵拿的是一支M1918A2“勃朗宁”自动步枪。为了在丛林中行进方便，该枪已拆除了两脚支架，一旦发现日军，这名枪手便可立即开枪采用连射火力对日军实施火力压制。","caption":""},{"image":"imgs/us/army/us_army_iwM1918Rifle_24.jpg","description":"1945年，太平洋战场，两名美国海军陆战队士兵在草丛中警惕地注视着前方。右边一名士兵拿的是一支M1918A2“勃朗宁”自动步枪，该枪优点是故障少，且射击时威力很大。","caption":""},{"image":"imgs/us/army/us_army_iwM1918Rifle_25.jpg","description":"1945年，太平洋战场冲绳岛战役，美军一名手持M1918A2“勃朗宁”自动步枪的军士带着一个战斗小队穿行在废墟中。","caption":""},{"image":"imgs/us/army/us_army_iwM1918Rifle_26.jpg","description":"1944年7月，西线战场法国诺曼底地区，美军第13兵团的士兵正向德军发起进攻。右前方冲锋的一名士兵拿着一支M1918A2“勃朗宁”自动步枪。","caption":""},{"image":"imgs/us/army/us_army_iwM1918Rifle_27.jpg","description":"1945年，西线战场德国境内，美军一名士兵手持M1918A2“勃朗宁”自动步枪指向一名站在窗台的德军俘虏。","caption":""},{"image":"imgs/us/army/us_army_iwM1918Rifle_28.jpg","description":"1945年，西线战场的比利时哈尔兹，一名美军士兵用M1918A2“勃朗宁”自动步枪向隐藏在远处房屋内的德军狙击手射击。","caption":""},{"image":"imgs/us/army/us_army_iwM1918Rifle_29.jpg","description":"1944年，西线战场法国马赛，一名法国士兵在街头用支起了两脚架的M1918A2“勃朗宁”自动步枪进行射击。在二战后期，有少量M1918A2“勃朗宁”自动步枪装备了盟军部队。","caption":""},{"image":"imgs/us/army/us_army_iwM1918Rifle_30.jpg","description":"1942年，两名美军士兵练习步枪对空射击，后面一名士兵拿的是一支M1918A2“勃朗宁”自动步枪。","caption":""},{"image":"imgs/us/army/us_army_iwM1918Rifle_31.jpg","description":"绘画：1944年，太平洋战场佩莱利乌岛战役中，一名美国海军陆战队士兵用M1918A2“勃朗宁”自动步枪向日军猛烈射击。","caption":""},{"image":"imgs/us/army/us_army_iwM1918Rifle_32.jpg","description":"绘画：1944年，太平洋战场马绍尔群岛战役中，一名手持M1918A2“勃朗宁”自动步枪的美国海军陆战队士兵在坦克掩护下向日军阵地前进。","caption":""},{"image":"imgs/us/army/us_army_iwM1918Rifle_33.jpg","description":"绘画：二战太平洋战场，一名美军士兵将M1918A2“勃朗宁”自动步枪的两脚架支在树干上向日军猛烈射击。由于该枪连射时后座力很大，在全自动射击时较难控制，所以在工事作战时会用上两脚支架，该枪射击时火力不亚于轻机枪。","caption":""},{"image":"imgs/us/army/us_army_iwM1918Rifle_34.jpg","description":"绘画：二战战场上，一名手持M1918A2“勃朗宁”自动步枪的美军士兵正在房屋窗口向外射击。由于该枪只有20发弹容量，自动射击时射速又很高，子弹一下子就会打光，因此该名士兵腰上挂满了子弹盒（按规定，每支枪配备12个弹匣）。","caption":""}]}')}});